Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 384,
  "height": 160,
  "padding": 0,
  "autosize": "none",
  "signals": [
    {
      "name": "abbr",
      "value": {
        "Obstetrics & Gynecology": "OB-GYN",
        "Ophthalmology": "Ophthal.",
        "Endocrinology": "Endocrin.",
        "Gastroenterology": "Gastro.",
        "Dermatology": "Derm.",
        "Orthopedics": "Ortho.",
        "General Medicine": "General Med.",
        "Neurology": "Neuro.",
        "Cardiology": "Cardio.",
        "Psychiatry": "Psych.",
        "Pediatrics": "Peds"
      }
    },
    {
      "name": "abbr2",
      "value": {
        "Obstetrics & Gynecology": "OB-GYN",
        "Ophthalmology": "Ophth.",
        "Endocrinology": "Endo.",
        "Gastroenterology": "GI",
        "Dermatology": "Derm.",
        "Orthopedics": "Ortho.",
        "General Medicine": "Gen. Med.",
        "Neurology": "Neuro.",
        "Cardiology": "Cardio.",
        "Psychiatry": "Psych.",
        "Pediatrics": "Peds"
      }
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "tree",
      "source": "dataset",
      "transform": [
        {
          "type": "filter",
          "expr": "datum[''Specialty''] != ''Not recorded'' && datum[''Valid Appointments''] > 0"
        },
        {
          "type": "window",
          "sort": {
            "field": "Valid Appointments",
            "order": "descending"
          },
          "ops": [
            "row_number"
          ],
          "as": [
            "rk"
          ]
        },
        {
          "type": "formula",
          "as": "grp",
          "expr": "datum.rk <= 8 ? datum[''Specialty''] : ''Other''"
        },
        {
          "type": "formula",
          "as": "rk2",
          "expr": "min(datum.rk, 9)"
        },
        {
          "type": "collect",
          "sort": {
            "field": "rk",
            "order": "ascending"
          }
        },
        {
          "type": "aggregate",
          "groupby": [
            "grp"
          ],
          "fields": [
            "Valid Appointments",
            "grp",
            "Specialty",
            "rk2"
          ],
          "ops": [
            "sum",
            "count",
            "values",
            "min"
          ],
          "as": [
            "value",
            "n",
            "members",
            "srt"
          ]
        },
        {
          "type": "collect",
          "sort": {
            "field": "srt",
            "order": "ascending"
          }
        },
        {
          "type": "nest",
          "keys": []
        },
        {
          "type": "treemap",
          "field": "value",
          "round": true,
          "sort": {
            "field": "srt",
            "order": "ascending"
          },
          "method": "squarify",
          "ratio": 1.3,
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height"
            }
          ],
          "paddingInner": 3
        },
        {
          "type": "filter",
          "expr": "datum.grp"
        },
        {
          "type": "formula",
          "as": "w",
          "expr": "datum.x1 - datum.x0"
        },
        {
          "type": "formula",
          "as": "h",
          "expr": "datum.y1 - datum.y0"
        },
        {
          "type": "formula",
          "as": "cnt",
          "expr": "format(datum.value, '','')"
        },
        {
          "type": "formula",
          "as": "full",
          "expr": "datum.grp == ''Other'' ? datum.n + '' others'' : datum.grp"
        },
        {
          "type": "formula",
          "as": "short_name",
          "expr": "abbr[datum.full] || datum.full"
        },
        {
          "type": "formula",
          "as": "tiny_name",
          "expr": "abbr2[datum.full] || datum.short_name"
        },
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.w >= length(datum.full) * 6.3 + 14 ? datum.full : datum.w >= length(datum.short_name) * 6.3 + 14 ? datum.short_name : datum.tiny_name"
        },
        {
          "type": "formula",
          "as": "low",
          "expr": "datum.h < 34"
        },
        {
          "type": "formula",
          "as": "inline",
          "expr": "datum.w >= length(datum.full + ''  '' + datum.cnt) * 6.3 + 14 ? datum.full + ''  '' + datum.cnt : datum.w >= length(datum.short_name + ''  '' + datum.cnt) * 6.3 + 14 ? datum.short_name + ''  '' + datum.cnt : datum.tiny_name + ''  '' + datum.cnt"
        },
        {
          "type": "formula",
          "as": "lab",
          "expr": "datum.low ? datum.inline : datum.name"
        }
      ]
    },
    {
      "name": "named",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.grp != ''Other''"
        }
      ]
    },
    {
      "name": "otherlist",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.grp == ''Other'' && datum.h >= 36 + 12 * datum.n"
        },
        {
          "type": "flatten",
          "fields": [
            "members"
          ],
          "as": [
            "m"
          ]
        },
        {
          "type": "formula",
          "as": "mv",
          "expr": "datum.m[''Valid Appointments'']"
        },
        {
          "type": "formula",
          "as": "ms",
          "expr": "datum.m[''Specialty'']"
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "k"
          ],
          "sort": {
            "field": "mv",
            "order": "descending"
          }
        },
        {
          "type": "formula",
          "as": "line",
          "expr": "(datum.w >= length(datum.ms + ''  '' + format(datum.mv, '','')) * 4.8 + 12 ? datum.ms : (abbr[datum.ms] || datum.ms)) + ''  '' + format(datum.mv, '','')"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "colour",
      "type": "linear",
      "domain": {
        "data": "named",
        "field": "value"
      },
      "range": [
        "#5598E7",
        "#104281"
      ]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "tree"
      },
      "encode": {
        "enter": {
          "cornerRadius": {
            "value": 5
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fill": [
            {
              "test": "datum.grp == ''Other''",
              "value": "#CBD2DD"
            },
            {
              "scale": "colour",
              "field": "value"
            }
          ],
          "tooltip": {
            "signal": "datum.grp == ''Other'' ? {''Group'': datum.n + '' other specialties'', ''Specialties'': join(pluck(datum.members, ''Specialty''), '', ''), ''Appointments'': datum.cnt} : {''Specialty'': datum.grp, ''Appointments'': datum.cnt}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tree"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "datum.x0 + 7"
          },
          "y": {
            "signal": "datum.low ? datum.y0 + datum.h / 2 + 3.5 : datum.y0 + 15"
          },
          "text": {
            "field": "lab"
          },
          "fill": [
            {
              "test": "datum.grp == ''Other''",
              "value": "#101828"
            },
            {
              "value": "#FFFFFF"
            }
          ],
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 10
          },
          "fontWeight": {
            "value": 600
          },
          "limit": {
            "signal": "datum.w - 10"
          },
          "opacity": {
            "signal": "datum.w > 30 && datum.h > 16 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tree"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "datum.x0 + 7"
          },
          "y": {
            "signal": "datum.y0 + 28"
          },
          "text": {
            "field": "cnt"
          },
          "fill": [
            {
              "test": "datum.grp == ''Other''",
              "value": "#344054"
            },
            {
              "value": "rgba(255,255,255,0.88)"
            }
          ],
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 9.5
          },
          "opacity": {
            "signal": "datum.w > 30 && !datum.low ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "otherlist"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "datum.x0 + 7"
          },
          "y": {
            "signal": "datum.y0 + 33 + 12 * datum.k"
          },
          "text": {
            "field": "line"
          },
          "fill": {
            "value": "#667085"
          },
          "font": {
            "value": "Segoe UI"
          },
          "fontSize": {
            "value": 9
          },
          "limit": {
            "signal": "datum.w - 10"
          }
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
